    function buildT(ctx) {
      try {
        ctx.locale.register(NS, 'zh', ZH)
        ctx.locale.register(NS, 'en', EN)
        const bound = ctx.locale.bind(NS)
        return (key) => {
          try {
            const value = bound(key)
            if (typeof value === 'string' && value) return value
          } catch {}
          return ZH[key] || key
        }
      } catch {
        return (key) => ZH[key] || key
      }
    }

    function mediaTypeOf(file) {
      if (file && typeof file.type === 'string' && file.type.indexOf('image/') === 0) return file.type
      const name = ((file && file.name) || '').toLowerCase()
      if (name.endsWith('.png')) return 'image/png'
      if (name.endsWith('.jpg') || name.endsWith('.jpeg')) return 'image/jpeg'
      if (name.endsWith('.webp')) return 'image/webp'
      if (name.endsWith('.gif')) return 'image/gif'
      return ''
    }

    function isImageFile(file) {
      return Boolean(mediaTypeOf(file))
    }

    function fileTypeOf(file) {
      const image = mediaTypeOf(file)
      if (image) return image
      const name = ((file && file.name) || '').toLowerCase()
      if (name.endsWith('.pdf')) return 'application/pdf'
      if (name.endsWith('.md')) return 'text/markdown'
      if (name.endsWith('.txt')) return 'text/plain'
      return ''
    }

    function isImportableFile(file) {
      return Boolean(fileTypeOf(file))
    }

    function isDocumentItem(item) {
      return Boolean(item && (item.kind === 'document' || (!item.image && item.text)))
    }

    function documentExtension(item) {
      const name = (item && item.document && item.document.name) || ''
      const match = String(name).match(/\.([a-z0-9]+)$/i)
      return match ? match[1].toUpperCase() : 'DOC'
    }

    async function request(path, options) {
      const response = await fetch(path, Object.assign({ cache: 'no-store' }, options || {}))
      let payload = null
      try { payload = await response.json() } catch {}
      if (!response.ok) throw new Error((payload && payload.error) || 'HTTP ' + response.status)
      return payload || {}
    }

    function pad(value) { return String(value).padStart(2, '0') }

    function isToday(iso) {
      const date = new Date(iso)
      const now = new Date()
      return date.getFullYear() === now.getFullYear() && date.getMonth() === now.getMonth() && date.getDate() === now.getDate()
    }

    function todayKey() {
      const now = new Date()
      return now.getFullYear() + '-' + pad(now.getMonth() + 1) + '-' + pad(now.getDate())
    }
    function localDateKey(iso) {
      const date = new Date(iso)
      return date.getFullYear() + '-' + pad(date.getMonth() + 1) + '-' + pad(date.getDate())
    }

    function dayNumber(dateKey) {
      const [year, month, day] = String(dateKey).split('-').map(Number)
      return Math.floor(Date.UTC(year, month - 1, day) / 86400000)
    }

    function dateKeyFromDayNumber(value) {
      const date = new Date(value * 86400000)
      return date.getUTCFullYear() + '-' + pad(date.getUTCMonth() + 1) + '-' + pad(date.getUTCDate())
    }

    function weekBounds(anchorKey) {
      const [year, month, day] = String(anchorKey).split('-').map(Number)
      const date = new Date(year, month - 1, day, 12)
      date.setDate(date.getDate() - ((date.getDay() + 6) % 7))
      const end = new Date(date)
      end.setDate(end.getDate() + 6)
      return { start: localDateKey(date.toISOString()), end: localDateKey(end.toISOString()) }
    }

    function periodBounds(period, anchorKey) {
      const [year, month, day] = String(anchorKey).split('-').map(Number)
      if (period === 'day') return { start: anchorKey, end: anchorKey }
      if (period === 'week') return weekBounds(anchorKey)
      if (period === 'month') {
        const start = new Date(year, month - 1, 1, 12)
        const end = new Date(year, month, 0, 12)
        return { start: localDateKey(start.toISOString()), end: localDateKey(end.toISOString()) }
      }
      return { start: year + '-01-01', end: year + '-12-31' }
    }

    function rangeText(start, end) {
      const [sy, sm, sd] = String(start).split('-').map(Number)
      const [ey, em, ed] = String(end).split('-').map(Number)
      if (sy === ey && sm === em && sd === ed) return sm + '月' + sd + '日'
      if (sy === ey) return sm + '月' + sd + '日 – ' + em + '月' + ed + '日'
      return sy + '年' + sm + '月 – ' + ey + '年' + em + '月'
    }

    function timeText(iso) {
      const date = new Date(iso)
      const now = new Date()
      const diff = now.getTime() - date.getTime()
      if (diff < 60_000) return '刚刚'
      if (diff < 3_600_000) return Math.floor(diff / 60_000) + ' 分钟前'
      if (isToday(iso)) return pad(date.getHours()) + ':' + pad(date.getMinutes())
      if (date.getFullYear() === now.getFullYear()) return (date.getMonth() + 1) + '月' + date.getDate() + '日'
      return date.getFullYear() + '/' + pad(date.getMonth() + 1) + '/' + pad(date.getDate())
    }

    function formatTokens(value) {
      const number = Number(value) || 0
      if (number >= 1_000_000) return (number / 1_000_000).toFixed(number >= 10_000_000 ? 0 : 1) + 'M'
      if (number >= 1_000) return (number / 1_000).toFixed(number >= 10_000 ? 0 : 1) + 'K'
      return String(Math.round(number))
    }

    function formatCost(value) {
      const number = Number(value) || 0
      if (!number) return '¥0.00'
      if (number < 0.01) return '< ¥0.01'
      return '¥' + number.toFixed(number < 1 ? 3 : 2)
    }

